class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in self.tickers:
            eq = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = eq.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A state
        self.a_shares = 0
        self.a_prev_close_above = None  # None until warmed up

        # Strategy B state
        self.b_shares = 0
        self.b_prev_close = None
        self.b_red_streak = 0
        self.b_prev_rsi_above60 = None

        self.prev_close_map = {}

        self.SetWarmUp(20)

    def OnData(self, data: Slice):

        # Ensure all tickers have data today; skip if any missing
        for t, sym in self.symbols.items():
            if not data.Bars.ContainsKey(sym):
                return

        if self.IsWarmingUp:
            self._update_prev_closes(data)
            return

        if not self.sma.IsReady or not self.rsi.IsReady:
            self._update_prev_closes(data)
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close
        sma_val = self.sma.Current.Value
        rsi_val = self.rsi.Current.Value

        prev_spy_close = self.prev_close_map.get(str(self.spy), None)
        prev_aapl_close = self.prev_close_map.get(str(self.aapl), None)

        if prev_spy_close is None or prev_aapl_close is None:
            self._update_prev_closes(data)
            return

        # need previous SMA value to check cross; compute using history? We track prev spy-vs-sma relationship
        # Determine current above/below relation
        curr_above = spy_close > sma_val
        curr_at_or_below = spy_close <= sma_val

        # We need yesterday's relation - stored in self.a_prev_close_above (relation of prev close to prev sma)
        # Since sma is streaming, prev sma automatically was value before this update... but Current.Value already updated to today.
        # We must have stored yesterday's relation from last bar processing.
        prev_relation_above = self.a_prev_close_above

        crossed_above = False
        crossed_below = False
        if prev_relation_above is not None:
            if prev_relation_above <= 0 and curr_above:
                crossed_above = True
            if prev_relation_above > 0 and not curr_above:
                crossed_below = True

        # ----- Strategy A: sell before buy -----
        if self.a_shares > 0:
            if crossed_below:
                self.MarketOrder(self.spy, -self.a_shares)
                self.a_shares = 0
        else:
            if crossed_above:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = 0.40 * portfolio_value
                qty = int(target_value // spy_close)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)
                    self.a_shares += qty

        # Update relation state for next bar
        self.a_prev_close_above = 1 if curr_above else 0

        # ----- Strategy B -----
        # Update red streak based on today's close vs prev close
        if aapl_close < prev_aapl_close:
            self.b_red_streak += 1
        else:
            self.b_red_streak = 0

        # sell before buy
        if self.b_shares > 0:
            if rsi_val > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        else:
            if self.b_red_streak >= 3:
                cash_available = self.Portfolio.Cash
                if cash_available >= 20000:
                    qty = int(20000 // aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares += qty

        self._update_prev_closes(data)

    def _update_prev_closes(self, data: Slice):
        for t, sym in self.symbols.items():
            if data.Bars.ContainsKey(sym):
                self.prev_close_map[str(sym)] = data.Bars[sym].Close

