from AlgorithmImports import *

class ParallelSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in tickers:
            eq = self.AddEquity(t, Resolution.Daily)
            self.symbols[t] = eq.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 50
        self.sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)

        self.rsi_period = 14
        self.rsi = self.RSI(self.aapl, self.rsi_period, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_close = {}

        self.prev_spy_close_above_sma = None

        self.a_shares = 0
        self.b_shares = 0

        self.aapl_red_streak = 0

        self.warmup_bars_needed = max(self.sma_period, self.rsi_period) + 2
        self.bar_count = 0

    def OnData(self, data: Slice):
        for t, sym in self.symbols.items():
            if not data.Bars.ContainsKey(sym):
                return

        self.bar_count += 1

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if not self.sma.IsReady or not self.rsi.IsReady:
            self._update_prev_closes(data)
            return

        if "AAPL" in self.prev_close:
            if aapl_close < self.prev_close["AAPL"]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        sma_value = self.sma.Current.Value
        spy_close_above_sma = spy_close > sma_value

        cross_above = False
        cross_below = False
        if self.prev_spy_close_above_sma is not None:
            prev_close_val = self.prev_close.get("SPY")
            if prev_close_val is not None:
                pass

        if self._has_full_history():
            prev_spy_close = self.prev_close.get("SPY")
            prev_sma_value = self.prev_sma_value if hasattr(self, "prev_sma_value") else None
            if prev_spy_close is not None and prev_sma_value is not None:
                was_le = prev_spy_close <= prev_sma_value
                is_gt = spy_close > sma_value
                cross_above = was_le and is_gt

                was_ge = prev_spy_close >= prev_sma_value
