        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.warmupDays = 100
        self.SetWarmUp(self.warmupDays, Resolution.Daily)

        # Strategy A state (SPY)
        self.lotA = 0
        self.prevSpyClose = None
        self.prevSpyAboveSma = None

        # Strategy B state (AAPL)
        self.lotB = 0
        self.aaplCloseHistory = []  # store last closes to track consecutive red days
        self.consecutiveRed = 0
        self.prevAaplClose = None

    def OnData(self, data: Slices):
        for t in self.tickers:
            sym = self.symbols[t]
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        spyClose = data[self.spy].Close
        aaplClose = data[self.aapl].Close
        aaplOpen = data[self.aapl].Open

        # Update AAPL red-day streak using previous close
        if self.prevAaplClose is not None:
            if aaplClose < self.prevAaplClose:
                self.consecutiveRed += 1
            else:
                self.consecutiveRed = 0

        # Determine SMA cross state
        smaReady = self.sma100.IsReady
        rsiReady = self.rsi14.IsReady

        if smaReady:
            currAboveSma = spyClose > self.sma100.Current.Value
            currBelowOrEqualSma = spyClose <= self.sma100.Current.Value

            crossAbove = False
            crossBelow = False
            if self.prevSpyAboveSma is not None:
                if (not self.prevSpyAboveSma) and currAboveSma:
                    crossAbove = True
                if self.prevSpyAboveSma and currBelowOrEqualSma:
                    crossBelow = True

            # Sell before buy
            if self.lotA > 0 and crossBelow:
                self.Liquidate(self.spy)
                self.lotA = 0
