                targetValue = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = int(targetValue // spyClose)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA = shares

            self.prevSpyAboveSma = currAboveSma

        # Strategy B logic
        if rsiReady:
            # Sell before buy
            if self.lotB > 0:
                if self.rsi14.Current.Value > 60:
                    self.Liquidate(self.aapl)
                    self.lotB = 0
            else:
                if self.consecutiveRed >= 3:
                    cost = 20000.0
                    if self.Portfolio.Cash >= cost:
                        shares = int(cost // aaplClose)
                        if shares > 0:
                            self.MarketOrder(self.aapl, shares)
                            self.lotB = shares

